    [Fact]
    public void Generated_records_compare_collection_members_by_value()
    {
        var mapLeft = new MapEntry("id", "name", new SourceLocator("source", "citation"))
            { AssertedBy = ["caller"] };
        var mapRight = new MapEntry("id", "name", new SourceLocator("source", "citation"))
            { AssertedBy = ["caller"] };
        var derivedLeft = new DerivedMapEntry("derived", "name", ["id"],
            [new SourceLocator("source", "citation")]) { AssertedBy = ["caller"] };
        var derivedRight = new DerivedMapEntry("derived", "name", ["id"],
            [new SourceLocator("source", "citation")]) { AssertedBy = ["caller"] };
        var registeredLeft = new RegisteredEntry("id", EntryStatus.Mapped, CorrespondenceRow.NotBuilt,
            [new SourceLocator("source", "citation")]) { AssertedBy = ["caller"] };
        var registeredRight = new RegisteredEntry("id", EntryStatus.Mapped, CorrespondenceRow.NotBuilt,
            [new SourceLocator("source", "citation")]) { AssertedBy = ["caller"] };

        Assert.Equal(mapLeft, mapRight);
        Assert.Equal(mapLeft.GetHashCode(), mapRight.GetHashCode());
        Assert.Equal(derivedLeft, derivedRight);
        Assert.Equal(derivedLeft.GetHashCode(), derivedRight.GetHashCode());
        Assert.Equal(registeredLeft, registeredRight);
        Assert.Equal(registeredLeft.GetHashCode(), registeredRight.GetHashCode());
    }

    private static void AssertDeclines(string entryId, UnresolvedReason reason, Resolution<object> typed, params SourceLocator[] cited)
    {
        foreach (var resolution in new[] { Registry.Resolve(entryId, RuleRequest.Empty), typed })
        {
            var unresolved = resolution.Match<UnresolvedResult?>(_ => null, u => u);
            Assert.NotNull(unresolved);
            Assert.Equal(reason, unresolved.Reason);
            Assert.Equal(cited[0], unresolved.Locator);
        }

        Assert.Equal(cited, Registry.Citations(entryId));
    }

    // The one request both paths can build is the one that states nothing (#692): a RuleRequest carries
    // assertions only, so the string path cannot state an input the engine declared on a request type.
    private static void AssertSameOutcome(Func<Resolution<object>> stringPath, Func<Resolution<object>> typedPath)
    {
        var viaString = Outcome(stringPath);
        var viaTyped = Outcome(typedPath);
        Assert.Equal(viaTyped.Thrown?.GetType(), viaString.Thrown?.GetType());
        if (viaString.Thrown is not null)
        {
            return;
        }

        Assert.Equal(viaTyped.Declined is null, viaString.Declined is null);
        if (viaString.Declined is null)
        {
            Assert.True(Equals(viaTyped.Value, viaString.Value), "the string and typed entry points resolved to different values");
            return;
        }

        Assert.Equal(viaTyped.Declined!.Reason, viaString.Declined.Reason);
        Assert.Equal(viaTyped.Declined.Locator, viaString.Declined.Locator);
        Assert.Equal(viaTyped.Declined.Attempted, viaString.Declined.Attempted);
    }

